css:
.label-container {
        width: 100%;
        margin: 0 auto;
        font-family: 'Inter', 'Helvetica Neue', Helvetica, Arial, sans-serif;
        color: #000;
        padding: 10px;
    }
    .label-header {
        text-align: center;
        margin-bottom: 20px;
        padding-bottom: 10px;
        border-bottom: 2px solid #d1d8dd;
    }
    .barcode-wrapper {
        text-align: center;
        margin: 20px 0;
        padding: 10px;
    }
    .barcode-wrapper svg, .barcode-wrapper img {
        max-width: 100%;
        height: 80px;
    }
    .custom-table {
        width: 100%;
        border-collapse: collapse;
        margin-bottom: 20px;
    }
    .custom-table th, .custom-table td {
        border: 1px solid #d1d8dd !important;
        padding: 10px 15px !important;
        font-size: 14px !important;
    }
    .custom-table th {
        background-color: #f8f9fa !important;
        -webkit-print-color-adjust: exact;
        color: #333 !important;
        font-weight: bold;
        width: 40%;
        text-align: left;
    }
    .custom-table td {
        color: #000 !important;
    }
    .capacities-section {
        margin-top: 25px;
    }
    .capacities-section h4 {
        font-size: 14px;
        font-weight: bold;
        margin-bottom: 10px;
        color: #333;
    }

    /* Ensure the HTML field table renders correctly without green borders */
    .html-table-wrapper table {
        width: 100% !important;
        border-collapse: collapse !important;
    }
    .html-table-wrapper th, .html-table-wrapper td {
        border: 1px solid #d1d8dd !important;
        padding: 8px 10px !important;
        font-size: 13px !important;
        text-align: left !important;
    }
    .html-table-wrapper th {
        background-color: #f8f9fa !important;
        color: #333 !important;
    }
